        actorId: reviewerId, actorKind: 'user', module: 'reviews', action: 'reviews.review.written',
        aggregateType: 'Review', aggregateId: reviewId, decisionCode: null, data: { targetUserId, targetKind, purchaseVerified, rating }, at: now,
